export async function createExport(attachmentId) {
  return fetch(`/api/admin/attachments/${attachmentId}/exports`, {
    method: 'POST',
  });
}

export async function shareExport(jobId) {
  return fetch(`/api/admin/exports/${jobId}/share`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: 'enabled=true',
  });
}
